local function createExtCard(model) local rarity=model:GetAttribute("Rarity") or "Unknown" local weight=model:GetAttribute("WeightKg") or model:GetAttribute("Weight") or 0 local zone=getAnimalZone(model) local cashPerSec=getCashPerSecond(model) local card=Instance.new("Frame") card.Size=UDim2.new(1,0,0,78) card.BackgroundColor3=Color3.fromRGB(24,22,36) card.BackgroundTransparency=0.15 Instance.new("UICorner",card).CornerRadius=UDim.new(0,12) Instance.new("UIStroke",card).Color=Color3.fromRGB(60,55,80) Instance.new("UIStroke",card).Transparency=0.6 local vp=Instance.new("ViewportFrame",card) vp.Size=UDim2.fromOffset(42,42) vp.Position=UDim2.new(0,8,0,8) vp.BackgroundColor3=Color3.fromRGB(20,18,32) vp.BorderSizePixel=0 Instance.new("UICorner",vp).CornerRadius=UDim.new(0,10) Instance.new("UIStroke",vp).Color=ACCENT Instance.new("UIStroke",vp).Transparency=0.6 setupViewportModel(vp,model) local mid=Instance.new("Frame",card) mid.Size=UDim2.new(1,-108,1,0) mid.Position=UDim2.new(0,58,0,0) mid.BackgroundTransparency=1 local nameLbl=Instance.new("TextLabel",mid) nameLbl.Size=UDim2.new(1,-72,0,12) nameLbl.Position=UDim2.new(0,0,0,6) nameLbl.BackgroundTransparency=1 nameLbl.Text=model.Name:upper() nameLbl.Font=Enum.Font.GothamBold nameLbl.TextSize=10 nameLbl.TextColor3=Color3.new(1,1,1) nameLbl.TextXAlignment=Enum.TextXAlignment.Left nameLbl.TextTruncate=Enum.TextTruncate.AtEnd local cashLbl=Instance.new("TextLabel",mid) cashLbl.Size=UDim2.new(0,68,0,12) cashLbl.Position=UDim2.new(1,-68,0,6) cashLbl.BackgroundTransparency=1 cashLbl.Text=cashPerSec cashLbl.Font=Enum.Font.GothamBold cashLbl.TextSize=10 cashLbl.TextColor3=Color3.fromRGB(80,255,120) cashLbl.TextXAlignment=Enum.TextXAlignment.Right cashLbl.TextTruncate=Enum.TextTruncate.AtEnd local kgLbl=Instance.new("TextLabel",mid) kgLbl.Size=UDim2.new(1,0,0,10) kgLbl.Position=UDim2.new(0,0,0,20) kgLbl.BackgroundTransparency=1 kgLbl.Text=tostring(weight).." KG • "..string.upper(rarity) kgLbl.Font=Enum.Font.GothamMedium kgLbl.TextSize=9 kgLbl.TextColor3=DIM kgLbl.TextXAlignment=Enum.TextXAlignment.Left local zoneLbl=Instance.new("TextLabel",mid) zoneLbl.Size=UDim2.new(1,0,0,10) zoneLbl.Position=UDim2.new(0,0,0,34) zoneLbl.BackgroundTransparency=1 zoneLbl.Text="📍 "..zone zoneLbl.Font=Enum.Font.GothamBold zoneLbl.TextSize=9 zoneLbl.TextColor3=ACCENT zoneLbl.TextXAlignment=Enum.TextXAlignment.Left local kg2=Instance.new("TextLabel",mid) kg2.Size=UDim2.new(1,0,0,10) kg2.Position=UDim2.new(0,0,0,48) kg2.BackgroundTransparency=1 kg2.Text=string.format("3 STUDS • %d SPD • %s/s",getWalkSpeed(),cashPerSec) kg2.Font=Enum.Font.GothamMedium kg2.TextSize=8 kg2.TextColor3=Color3.fromRGB(100,95,120) kg2.TextXAlignment=Enum.TextXAlignment.Left local btn=Instance.new("TextButton",card) btn.Size=UDim2.fromOffset(44,26) btn.Position=UDim2.new(1,-50,0.5,-13) btn.Text="STEAL" btn.Font=Enum.Font.GothamBold btn.TextSize=9 btn.TextColor3=Color3.new(1,1,1) btn.BackgroundColor3=ACCENT Instance.new("UICorner",btn).CornerRadius=UDim.new(0,8) btn.AutoButtonColor=false btn.MouseButton1Click:Connect(function() stealMethod(model) end) return card end
local function refreshExternal() for _,v in ipairs(extScroll:GetChildren()) do if v:IsA("Frame") then v:Destroy() end end local folder=workspace:FindFirstChild("AnimalPickups") if not folder then return end local list={} for _,m in ipairs(folder:GetChildren()) do if m:IsA("Model") then table.insert(list,m) end end table.sort(list,function(a,b) local sa=getRarityScore(a:GetAttribute("Rarity") or "") local sb=getRarityScore(b:GetAttribute("Rarity") or "") if sa~=sb then return sa>sb end return (a:GetAttribute("WeightKg") or 0)>(b:GetAttribute("WeightKg") or 0) end) for _,m in ipairs(list) do createExtCard(m).Parent=extScroll end end
