-- BIG EGG
local function getEggSize(model) for _,a in ipairs({"Size","EggSize","Scale","WeightKg","Weight","SizeMultiplier"}) do local v=model:GetAttribute(a) if typeof(v)=="number" then return v end end for _,d in ipairs(model:GetDescendants()) do if d:IsA("NumberValue") and d.Name:lower():find("size") then return d.Value end end local ok,_,sz=pcall(function() return model:GetBoundingBox() end) if ok and sz then return sz.Magnitude end return 0 end
local function getEggsInZone(zoneName) local zb=getZoneBuildsFolder() if not zb then return {} end local zoneModel=zb:FindFirstChild(zoneName) if not zoneModel then return {} end local eggsRoot=zoneModel:FindFirstChild("Eggs") or zoneModel local out={} for _,v in ipairs(eggsRoot:GetChildren()) do if v:IsA("Model") and v.Name:lower():find("egg") then table.insert(out,v) end end if #out==0 then for _,v in ipairs(eggsRoot:GetDescendants()) do if v:IsA("Model") and v.Name:lower():find("egg") then table.insert(out,v) end end end if bigEggPriority then table.sort(out,function(a,b) return getEggSize(a)>getEggSize(b) end) end return out end
local function getEggHealth(eggModel) if eggModel:GetAttribute("Health") then return eggModel:GetAttribute("Health") end for _,d in ipairs(eggModel:GetDescendants()) do local h=d:GetAttribute("Health") if h~=nil then return h end end return nil end
local function equipPickaxe() local char=plr.Character if not char then return nil end local tool=char:FindFirstChildOfClass("Tool") if tool and tool.Name:lower():find("pickaxe") then return tool end for _,t in ipairs(plr.Backpack:GetChildren()) do if t:IsA("Tool") and t.Name:lower():find("pickaxe") then t.Parent=char return t end end for _,t in ipairs(plr.Backpack:GetChildren()) do if t:IsA("Tool") then t.Parent=char return t end end return char:FindFirstChildOfClass("Tool") end

bigEggToggle.btn.MouseButton1Click:Connect(function() bigEggPriority=not bigEggPriority if bigEggPriority then tw(bigEggToggle.track,{BackgroundColor3=ACCENT},0.2):Play() tw(bigEggToggle.dot,{Position=UDim2.new(1,-21,0.5,-9)},0.25,Enum.EasingStyle.Back):Play() tw(bigEggToggle.accent,{BackgroundColor3=ACCENT},0.2):Play() Window.Notify("BIG EGG","Priority ON - Biggest First",ACCENT,2) else tw(bigEggToggle.track,{BackgroundColor3=Color3.fromRGB(34,30,50)},0.2):Play() tw(bigEggToggle.dot,{Position=UDim2.new(0,3,0.5,-9)},0.25,Enum.EasingStyle.Back):Play() tw(bigEggToggle.accent,{BackgroundColor3=Color3.fromRGB(60,55,80)},0.2):Play() Window.Notify("BIG EGG","OFF",DIM,2) end end)

local breakOn=false
eggToggle.btn.MouseButton1Click:Connect(function() breakOn=not breakOn if breakOn then if not selectedEggZone then breakOn=false Window.Notify("ERROR","Pilih Zone dulu!",Color3.fromRGB(248,113,113),2) return end tw(eggToggle.track,{BackgroundColor3=Color3.fromRGB(255,220,90)},0.25):Play() tw(eggToggle.dot,{Position=UDim2.new(1,-21,0.5,-9)},0.25,Enum.EasingStyle.Back):Play() tw(eggToggle.accent,{BackgroundColor3=Color3.fromRGB(255,220,90)},0.25):Play() task.spawn(function() while breakOn do local targets=getStealTargets() if #targets>0 then for _,m in ipairs(targets) do if not breakOn then break end pcall(function() stealMethod(m) end) task.wait(0.3) end continue end local eggs=getEggsInZone(selectedEggZone) if #eggs==0 then task.wait(1) continue end for _,egg in ipairs(eggs) do if not breakOn then break end if #getStealTargets()>0 then break end local pos,base=getOffsetPos(egg) if not pos then local b=getBasePos(egg) if b then pos=Vector3.new(b.X,3.5,b.Z+3) base=Vector3.new(b.X,3.5,b.Z) end end if not pos then continue end pcall(function() walkDirect(pos,base,false) equipPickaxe() while breakOn and egg.Parent do if #getStealTargets()>0 then break end local h=getEggHealth(egg) if h==nil or h<=0 then break end task.wait(0.15) end end) task.wait(0.2) end task.wait(0.5) end end) else tw(eggToggle.track,{BackgroundColor3=Color3.fromRGB(34,30,50)},0.25):Play() tw(eggToggle.dot,{Position=UDim2.new(0,3,0.5,-9)},0.25,Enum.EasingStyle.Back):Play() tw(eggToggle.accent,{BackgroundColor3=Color3.fromRGB(60,55,80)},0.25):Play() end end)

